#include "room_publication_clock.hpp"
#include "room_json.hpp"
#include <iostream>
using namespace wot::room;
int main(){std::string line;while(std::getline(std::cin,line)){try{const auto input=parseJson(line);PublicationClock clock;State state;state.bot_state_time_us=intField(input,"mapped",0);state.server_time_ms=intField(input,"time",10000);Value out=array();for(const auto&op:rows(input.get("operations"))){Value row=object();if(op.get("producer_changed").truth()){clock.producerChanged();state.bot_launch_clock_offset_us.reset();row.object["changed"]=boolean(true);}else try{state.server_time_ms=intField(op,"time",state.server_time_ms);const auto proposal=clock.stage(op.get("message"),state,intField(op,"receipt"));row.object["mapped"]=integer(proposal.mapped_sample);row.object["motion_offset"]=integer(proposal.motion_offset);row.object["launch_offset"]=proposal.launch_offset?integer(*proposal.launch_offset):Value{};row.object["source"]=proposal.source?integer(*proposal.source):Value{};row.object["horizon"]=proposal.horizon?integer(*proposal.horizon):Value{};row.object["rebase"]=boolean(proposal.rebase);row.object["same_batch"]=boolean(proposal.same_batch);if(!has(op,"commit")||op.get("commit").truth())clock.commit(state,proposal);}catch(const PublicationClock::Failure&e){row.object["rejected"]=text(e.code);}row.object["state_mapped"]=integer(state.bot_state_time_us);row.object["motion_now"]=integer(clock.motionTime(intField(op,"receipt")));row.object["state_launch_offset"]=state.bot_launch_clock_offset_us?integer(*state.bot_launch_clock_offset_us):Value{};out.array.push_back(std::move(row));}std::cout<<writeJson(out)<<'\n';}catch(const std::exception&e){auto v=object();v.object["error"]=text(e.what());std::cout<<writeJson(v)<<'\n';}}}
